ep_signup.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let username = req.username ?? "";
let email = req.email ?? "";
let password = req.password ?? "";
let profile = req.profile ?? {};
if (username == "" || email == "" || password == "") {
  return {created: false, statusCode: 400, reason: "username, email and password are required"};
} else {
  let users = vdb.collection("auth_users");
  let lookup = users.find({username: {$eq: username}}, 1);
  let rows = lookup.data ?? [];
  if (leng(rows) > 0) {
    return {created: false, statusCode: 409, reason: "User already exists", username: username};
  } else {
    let nowTs = datetime.now().isoformat();
    let storedHash = crypto.sha256(password);
    let defaultRbac = {scopes: ["USER"], abilities: ["auth.self.read", "auth.self.update"]};
    let created = users.insert({username: username, email: email, passwordHash: storedHash, role: "USER", profile: profile, rbac: defaultRbac, createdAt: nowTs, updatedAt: nowTs});
    return {created: created.ok ?? false, statusCode: created.ok == false ? 500 : 201, reason: created.ok == false ? (created.error ?? "Failed to create user") : "User created", username: username, role: "USER", inserted: created.data ?? created, authModel: "AuthUser"};
  }
}

ep_signin.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let identifier = str(body.identifier ?? body.login ?? req.identifier ?? req.login ?? "").trim();
let username = str(body.username ?? req.username ?? "").trim();
let email = str(body.email ?? req.email ?? "").trim();
let password = str(body.password ?? req.password ?? "").trim();
if (username == "" && email == "" && identifier != "") {
  if (identifier.contains("@")) {
    email = identifier;
  } else {
    username = identifier;
  }
}
if ((username == "" && email == "") || password == "") {
  return {authenticated: false, tokenType: "Bearer", accessToken: "", statusCode: 400, reason: "username or email and password are required"};
} else {
  let users = vdb.collection("auth_users");
  let rows = [];
  if (username != "") {
    let usernameLookup = users.find({username: {$eq: username}}, 1);
    rows = usernameLookup.data ?? [];
  }
  if (leng(rows) == 0 && email != "") {
    let emailLookup = users.find({email: {$eq: email}}, 1);
    rows = emailLookup.data ?? [];
  }
  if (leng(rows) == 0) {
    return {authenticated: false, tokenType: "Bearer", accessToken: "", statusCode: 401, reason: "Invalid credentials"};
  } else {
    let user = rows[0];
    let storedHash = user.passwordHash ?? "";
    let incomingHash = crypto.sha256(password);
    if (storedHash == "" || incomingHash != storedHash) {
      return {authenticated: false, tokenType: "Bearer", accessToken: "", statusCode: 401, reason: "Invalid credentials"};
    } else {
      let controls = vdb.collection("auth_session_controls");
      let controlLookup = controls.find({username: {$eq: user.username ?? username}}, 1);
      let controlRows = controlLookup.data ?? [];
      let sessionVersion = 1;
      if (leng(controlRows) > 0) {
        let currentVersion = controlRows[0].sessionVersion ?? 1;
        if (currentVersion != "") {
          sessionVersion = currentVersion;
        }
      }
      let claims = {
        sub: user.username ?? username,
        purpose: "access",
        token_use: "bearer",
        username: user.username ?? username,
        email: user.email ?? email,
        role: user.role ?? "USER",
        rbac: user.rbac ?? {scopes: ["USER"]},
        sessionVersion: sessionVersion
      };
      let token = jwt.sign(claims, req.jwtSecret ?? "AuthCoreService::liwiro", {algorithm: "HS256", issuer: "AuthCoreService", audience: body.audience ?? req.audience ?? "liwiro", expiresInSeconds: body.expiresInSeconds ?? req.expiresInSeconds ?? 3600});
      return {authenticated: true, algorithm: "HS256", tokenType: "Bearer", token: token, accessToken: token, tokenOnly: token, claims: claims, reason: "OK"};
    }
  }
}

ep_me.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let authCtx = req.auth ?? {};
let username = str(authCtx.username ?? authCtx.sub ?? "").trim();
if (username == "") {
  return {ok: false, statusCode: 401, reason: "Missing authenticated user context"};
}

let users = vdb.collection("auth_users");
let userLookup = users.find({username: {$eq: username}}, 1);
let userRows = userLookup.data ?? [];
if (leng(userRows) == 0) {
  return {ok: false, statusCode: 404, reason: "Authenticated user no longer exists", username: username};
}

let dbUser = userRows[0];
let controls = vdb.collection("auth_session_controls");
let controlLookup = controls.find({username: {$eq: username}}, 1);
let controlRows = controlLookup.data ?? [];
let sessionControl = leng(controlRows) > 0 ? controlRows[0] : {};
let effectiveRbac = type(dbUser.rbac) == "object" ? dbUser.rbac : (type(authCtx.rbac) == "object" ? authCtx.rbac : {scopes: ["USER"]});
let effectiveSessionVersion = sessionControl.sessionVersion ?? authCtx.sessionVersion ?? 1;

let userPayload = {
  username: username,
  email: str(dbUser.email ?? authCtx.email ?? "").trim(),
  role: str(dbUser.role ?? authCtx.role ?? "USER").upper(),
  profile: dbUser.profile ?? {},
  rbac: effectiveRbac,
  sessionVersion: effectiveSessionVersion,
  createdAt: dbUser.createdAt ?? "",
  updatedAt: dbUser.updatedAt ?? "",
  updatedBy: dbUser.updatedBy ?? ""
};

return {ok: true, user: userPayload};

ep_forgot_password.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let username = str(req.username ?? req.userame ?? "").trim();
let identifier = str(req.identifier ?? req.login ?? "").trim();
let emailRaw = str(req.email ?? "").trim();
let emailInput = emailRaw.lower();
if (username == "" && emailInput == "" && identifier != "") {
  if (identifier.contains("@")) {
    emailRaw = identifier;
    emailInput = identifier.lower();
  } else {
    username = identifier;
  }
}
if (username == "" && emailInput == "") {
  return {ok: false, statusCode: 400, reason: "username or email is required"};
} else {
  let users = vdb.collection("auth_users");
  let rows = [];
  if (username != "") {
    let usernameLookup = users.find({username: {$eq: username}}, 1);
    rows = usernameLookup.data ?? [];
  }
  if (leng(rows) == 0 && emailRaw != "") {
    let emailLookup = users.find({email: {$eq: emailRaw}}, 1);
    rows = emailLookup.data ?? [];
  }
  if (leng(rows) == 0 && emailInput != "" && emailInput != emailRaw) {
    let emailLookupLower = users.find({email: {$eq: emailInput}}, 1);
    rows = emailLookupLower.data ?? [];
  }
  if (leng(rows) == 0) {
    return {ok: false, statusCode: 404, reason: "User not found"};
  } else {
    let user = rows[0];
    let recipient = str(user.email ?? emailRaw ?? emailInput).trim();
    if (recipient == "") {
      return {ok: false, statusCode: 400, reason: "User has no email"};
    } else {
      let expiresInSeconds = req.expiresInSeconds ?? 900;
      if (expiresInSeconds == "") {
        expiresInSeconds = 900;
      }
      let tokenId = crypto.uuid();
      let resetToken = jwt.sign({sub: user.username ?? "", email: recipient, jti: tokenId, purpose: "password_reset", token_use: "password_reset"}, req.jwtSecret ?? "AuthCoreService::liwiro", {algorithm: "HS256", issuer: "AuthCoreService", audience: "password-reset", expiresInSeconds: expiresInSeconds});
      let tokenStore = vdb.collection("auth_password_reset_tokens");
      let nowInfo = datetime.now();
      let nowTs = nowInfo.isoformat();
      let tokenHash = crypto.sha256(resetToken);
      let expiresAt = (nowInfo.timestamp ?? 0) + expiresInSeconds;
      let tokenDoc = {
        jti: tokenId,
        username: user.username ?? "",
        recipient: recipient,
        tokenHash: tokenHash,
        status: "issued",
        expiresAt: expiresAt,
        createdAt: nowTs,
        usedAt: ""
      };
      let tokenSave = tokenStore.insert(tokenDoc);
      if (tokenSave.ok == false) {
        return {ok: false, statusCode: 500, reason: tokenSave.error ?? "Failed to persist reset token", result: tokenSave};
      }
      let configuredReset = service.env.PASSWORD_RESET_URL ?? "";
      let localBase = "http://127.0.0.1:" + str(service.env.PORT ?? "") + service.basePath + "/reset-password";
      let baseReset = configuredReset != "" ? configuredReset : localBase;
      let sep = baseReset.contains("?") ? "&" : "?";
      let resetLink = baseReset + sep + "token=" + resetToken;
      let smtpHost = str(service.env.EMAIL_SMTP_HOST ?? "").trim();
      let smtpUser = str(service.env.EMAIL_SMTP_USERNAME ?? "").trim();
      let smtpPass = str(service.env.EMAIL_SMTP_PASSWORD ?? "").trim();
      if (smtpHost == "" || smtpUser == "" || smtpPass == "") {
        return {ok: true, status: "skipped", reason: "SMTP not configured; reset link generated", recipient: recipient, resetLink: resetLink, resetTokenId: tokenId, expiresInSeconds: expiresInSeconds};
      }
      let emailResult = email.send({host: smtpHost, port: service.env.EMAIL_SMTP_PORT ?? 587, startTls: service.env.EMAIL_SMTP_STARTTLS ?? true, ssl: service.env.EMAIL_SMTP_SSL ?? false, auth: service.env.EMAIL_SMTP_AUTH ?? true, username: smtpUser, password: smtpPass, from: service.env.EMAIL_FROM, to: [recipient], subject: "Password Reset Request", body: "Reset link: " + resetLink});
      return {ok: emailResult.ok == true, status: emailResult.status, reason: emailResult.ok == true ? "Reset email sent" : (emailResult.error ?? "Failed to send reset email"), recipient: recipient, resetLink: resetLink, resetTokenId: tokenId, expiresInSeconds: expiresInSeconds, email: emailResult};
    }
  }
}

ep_reset_password.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let body = req.body ?? {};
let token = str(body.token ?? req.token ?? "").trim();
let newPassword = str(body.newPassword ?? req.newPassword ?? "").trim();
if (token == "" || newPassword == "") {
  return {ok: false, statusCode: 400, reason: "token and newPassword are required"};
} else {
  let verified = jwt.verify(token, req.jwtSecret ?? "AuthCoreService::liwiro", {algorithm: "HS256", issuer: "AuthCoreService", audience: "password-reset"});
  if (!(verified.valid ?? false)) {
    return {ok: false, statusCode: 400, reason: verified.error ?? "Invalid reset token"};
  } else {
    let claims = verified.payload ?? {};
    let purpose = str(claims.purpose ?? claims.token_use ?? "").lower();
    if (purpose != "password_reset" && purpose != "password-reset") {
      return {ok: false, statusCode: 400, reason: "Invalid reset token purpose"};
    }
    let subject = str(claims.sub ?? "").trim();
    let tokenId = str(claims.jti ?? "").trim();
    if (subject == "" || tokenId == "") {
      return {ok: false, statusCode: 400, reason: "Invalid reset token"};
    }
    let tokenStore = vdb.collection("auth_password_reset_tokens");
    let tokenLookup = tokenStore.find({jti: {$eq: tokenId}}, 1);
    let tokenRows = tokenLookup.data ?? [];
    if (leng(tokenRows) == 0) {
      return {ok: false, statusCode: 400, reason: "Reset token already used or unknown"};
    }
    let tokenDoc = tokenRows[0];
    let tokenStatus = str(tokenDoc.status ?? "issued").lower();
    if (tokenStatus != "issued" || str(tokenDoc.usedAt ?? "").trim() != "") {
      return {ok: false, statusCode: 400, reason: "Reset token has already been used"};
    }
    let storedHash = str(tokenDoc.tokenHash ?? "").trim();
    let incomingHash = crypto.sha256(token);
    if (storedHash == "" || storedHash != incomingHash) {
      return {ok: false, statusCode: 400, reason: "Reset token mismatch"};
    }
    let nowInfo = datetime.now();
    let nowEpoch = nowInfo.timestamp ?? 0;
    let expiresAt = tokenDoc.expiresAt ?? 0;
    if (expiresAt != "" && expiresAt < nowEpoch) {
      let expireRes = tokenStore.update({jti: {$eq: tokenId}}, {status: "expired"});
      return {ok: false, statusCode: 400, reason: "Reset token expired", expireResult: expireRes};
    }
    let nowTs = nowInfo.isoformat();
    let consumeRes = tokenStore.update({jti: {$eq: tokenId}}, {status: "used", usedAt: nowTs, tokenHash: ""});
    if (consumeRes.ok == false) {
      return {ok: false, statusCode: 500, reason: consumeRes.error ?? "Failed to consume reset token", result: consumeRes};
    }
    let users = vdb.collection("auth_users");
    let lookup = users.find({username: {$eq: subject}}, 1);
    let rows = lookup.data ?? [];
    if (leng(rows) == 0) {
      return {ok: false, notFound: true, statusCode: 404, reason: "User not found"};
    } else {
      let passwordHash = crypto.sha256(newPassword);
      let updateRes = users.update({username: {$eq: subject}}, {passwordHash: passwordHash, password: "", updatedAt: nowTs, passwordResetAt: nowTs});
      if (!(updateRes.ok ?? false)) {
        return {ok: false, statusCode: 400, reason: updateRes.error ?? "Password reset failed", result: updateRes};
      }
      let controls = vdb.collection("auth_session_controls");
      let existing = controls.find({username: {$eq: subject}}, 1);
      let controlRows = existing.data ?? [];
      let nextSessionVersion = 1;
      if (leng(controlRows) > 0) {
        let currentVersion = controlRows[0].sessionVersion ?? 1;
        if (currentVersion != "") {
          nextSessionVersion = currentVersion + 1;
        }
      }
      let revokePayload = {username: subject, sessionVersion: nextSessionVersion, revokeAll: true, revokedAt: nowTs, excludeCurrentSession: false, excludedTokenHash: "", updatedAt: nowTs, updatedBy: subject, reason: "password_reset"};
      let revokeSave = {};
      if (leng(controlRows) > 0) {
        revokeSave = controls.update({username: {$eq: subject}}, revokePayload);
      } else {
        revokeSave = controls.insert(revokePayload);
      }
      return {ok: true, reason: "Password reset successful", username: subject, resetTokenId: tokenId, tokenConsumed: true, sessionsRevoked: revokeSave.ok ?? true, sessionVersion: nextSessionVersion, result: updateRes, revokeResult: revokeSave};
    }
  }
}

ep_users_read.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

func normalize_eq(value) {
  if (type(value) == "object") {
    return str(value["$eq"] ?? "").trim();
  }
  return str(value ?? "").trim();
}

func own_query_allowed(query, actor, actorEmail) {
  if (type(query) != "object") {
    return false;
  }
  if (leng(query.keys()) == 0) {
    return false;
  }
  let usernameEq = normalize_eq(query.username ?? "");
  if (usernameEq != "" && usernameEq == actor) {
    return true;
  }
  let emailEq = normalize_eq(query.email ?? "");
  if (emailEq != "" && actorEmail != "" && emailEq.lower() == actorEmail.lower()) {
    return true;
  }
  return false;
}

func sanitize_user(row) {
  let safeUser = {
    username: row.username ?? "",
    email: row.email ?? "",
    role: row.role ?? "USER",
    profile: row.profile ?? {},
    rbac: row.rbac ?? {scopes: ["USER"]},
    createdAt: row.createdAt ?? "",
    updatedAt: row.updatedAt ?? ""
  };
  return safeUser;
}

let req = params;
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "").trim();
if (actor == "") {
  return {ok: false, authorized: false, statusCode: 401, reason: "Missing authenticated user context"};
}
let actorEmail = str(authCtx.email ?? "").trim();
let actorRole = str(authCtx.role ?? "USER").upper();
let isPrivileged = actorRole == "SUPER_ADMIN" || actorRole == "ADMIN";
let query = req.query ?? {};
if (type(query) != "object") {
  return {ok: false, statusCode: 400, reason: "Query must be a JSON object"};
}
if (!isPrivileged && !own_query_allowed(query, actor, actorEmail)) {
  return {ok: false, authorized: false, statusCode: 403, reason: "Regular users must query their own username or email explicitly"};
}
let users = vdb.collection("auth_users");
let lookup = users.find(query, req.limit ?? 200);
let rows = lookup.data ?? [];
if (leng(rows) == 0 && leng(query.keys()) > 0) {
  return {ok: false, notFound: true, statusCode: 404, reason: "No users matched the supplied query", query: query};
}
let usersOut = [];
let ownOnly = true;
for (row : rows) {
  let sanitized = sanitize_user(row ?? {});
  usersOut.add(sanitized);
  if (str(sanitized.username ?? "").trim() != actor) {
    ownOnly = false;
  }
}
let primary = leng(usersOut) > 0 ? usersOut[0] : {};
return {ok: true, users: usersOut, user: primary, count: leng(usersOut), ownView: ownOnly, query: query, requestedBy: actor, privileged: isPrivileged};

ep_users_update.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

func normalize_eq(value) {
  if (type(value) == "object") {
    return str(value["$eq"] ?? "").trim();
  }
  return str(value ?? "").trim();
}

func own_query_allowed(query, actor, actorEmail) {
  if (type(query) != "object") {
    return false;
  }
  if (leng(query.keys()) == 0) {
    return false;
  }
  let usernameEq = normalize_eq(query.username ?? "");
  if (usernameEq != "" && usernameEq == actor) {
    return true;
  }
  let emailEq = normalize_eq(query.email ?? "");
  if (emailEq != "" && actorEmail != "" && emailEq.lower() == actorEmail.lower()) {
    return true;
  }
  return false;
}

func sanitize_user(row, updates) {
  let safeUser = {
    username: row.username ?? "",
    email: updates.email ?? row.email ?? "",
    role: updates.role ?? row.role ?? "USER",
    profile: updates.profile ?? row.profile ?? {},
    rbac: updates.rbac ?? row.rbac ?? {scopes: ["USER"]},
    updatedAt: updates.updatedAt ?? row.updatedAt ?? "",
    updatedBy: updates.updatedBy ?? row.updatedBy ?? ""
  };
  return safeUser;
}

let req = params;
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "").trim();
if (actor == "") {
  return {updated: false, authorized: false, statusCode: 401, reason: "Missing authenticated user context"};
}
let actorEmail = str(authCtx.email ?? "").trim();
let actorRole = str(authCtx.role ?? "USER").upper();
let isPrivileged = actorRole == "SUPER_ADMIN" || actorRole == "ADMIN";
let query = req.query ?? {};
if (type(query) != "object") {
  return {updated: false, statusCode: 400, reason: "Query must be a JSON object"};
}
if (!isPrivileged && !own_query_allowed(query, actor, actorEmail)) {
  return {updated: false, authorized: false, statusCode: 403, reason: "Regular users must query their own username or email explicitly"};
}
let body = req.body ?? {};
let bodyUsername = str(body.username ?? "").trim();
if (bodyUsername != "") {
  return {updated: false, statusCode: 400, reason: "username cannot be changed through this route; use the query object to select records"};
}
let requestedRole = str(body.role ?? "").upper();
if (requestedRole == "APP") {
  requestedRole = "APPLICATION";
}
let requestedRbac = body.rbac ?? "";
let emailPatch = str(body.email ?? "").trim();
let profilePatch = body.profile ?? "";
let newPassword = str(body.password ?? body.newPassword ?? "").trim();
if (actorRole == "USER" && requestedRole != "") {
  return {updated: false, authorized: false, statusCode: 403, reason: "Regular users cannot change roles"};
}
if (actorRole == "USER" && requestedRbac != "") {
  return {updated: false, authorized: false, statusCode: 403, reason: "Regular users cannot change RBAC grants"};
}
if (actorRole != "SUPER_ADMIN" && (requestedRole == "ADMIN" || requestedRole == "SUPER_ADMIN")) {
  return {updated: false, authorized: false, statusCode: 403, reason: "Only SUPER_ADMIN can assign ADMIN or SUPER_ADMIN roles"};
}
let users = vdb.collection("auth_users");
let lookup = users.find(query, req.limit ?? 200);
let rows = lookup.data ?? [];
if (leng(rows) == 0) {
  return {updated: false, notFound: true, statusCode: 404, reason: "No users matched the supplied query", query: query};
}
for (row : rows) {
  let targetRole = str((row ?? {}).role ?? "USER").upper();
  if (actorRole == "ADMIN" && targetRole == "SUPER_ADMIN") {
    return {updated: false, authorized: false, statusCode: 403, reason: "ADMIN users cannot edit SUPER_ADMIN accounts"};
  }
}
let nowTs = datetime.now().isoformat();
let updates = {updatedAt: nowTs, updatedBy: actor};
let validUpdateCount = 0;
if (emailPatch != "") {
  updates.email = emailPatch;
  validUpdateCount += 1;
}
if (profilePatch != "") {
  updates.profile = profilePatch;
  validUpdateCount += 1;
}
if (requestedRole != "") {
  updates.role = requestedRole;
  validUpdateCount += 1;
}
if (requestedRbac != "") {
  updates.rbac = requestedRbac;
  validUpdateCount += 1;
}
let passwordChanged = false;
if (newPassword != "") {
  updates.passwordHash = crypto.sha256(newPassword);
  updates.password = "";
  updates.passwordChangedAt = nowTs;
  passwordChanged = true;
  validUpdateCount += 1;
}
if (validUpdateCount == 0) {
  return {updated: false, statusCode: 400, reason: "No valid updates provided"};
}
let updateRes = users.update(query, updates);
if (!(updateRes.ok ?? false)) {
  return {updated: false, statusCode: 400, reason: updateRes.error ?? "Update failed", result: updateRes};
}
let revokedUsers = [];
let revokeFailures = [];
if (passwordChanged) {
  let controls = vdb.collection("auth_session_controls");
  for (row : rows) {
    let targetUsername = str((row ?? {}).username ?? "").trim();
    if (targetUsername == "") {
      continue;
    }
    let existing = controls.find({username: {$eq: targetUsername}}, 1);
    let controlRows = existing.data ?? [];
    let sessionVersion = 1;
    if (leng(controlRows) > 0) {
      let currentVersion = controlRows[0].sessionVersion ?? 1;
      if (currentVersion != "") {
        sessionVersion = currentVersion + 1;
      }
    }
    let revokePayload = {username: targetUsername, sessionVersion: sessionVersion, revokeAll: true, revokedAt: nowTs, excludeCurrentSession: false, excludedTokenHash: "", updatedAt: nowTs, updatedBy: actor, reason: "password_changed"};
    let revokeSave = {};
    if (leng(controlRows) > 0) {
      revokeSave = controls.update({username: {$eq: targetUsername}}, revokePayload);
    } else {
      revokeSave = controls.insert(revokePayload);
    }
    if (revokeSave.ok == false) {
      revokeFailures.add({username: targetUsername, result: revokeSave});
    } else {
      revokedUsers.add({username: targetUsername, sessionVersion: sessionVersion});
    }
  }
}
let usersOut = [];
let ownOnly = true;
for (row : rows) {
  let sanitized = sanitize_user(row ?? {}, updates);
  usersOut.add(sanitized);
  if (str(sanitized.username ?? "").trim() != actor) {
    ownOnly = false;
  }
}
let statusCode = leng(revokeFailures) > 0 ? 500 : 200;
return {updated: true, statusCode: statusCode, users: usersOut, count: leng(usersOut), ownUpdate: ownOnly, passwordChanged: passwordChanged, sessionsRevoked: passwordChanged ? leng(revokeFailures) == 0 : false, revokedUsers: revokedUsers, revokeFailures: revokeFailures, query: query, result: updateRes};

