let actorEmail = str(authCtx.email ?? "").trim();
let actorRole = str(authCtx.role ?? "USER").upper();
let isPrivileged = actorRole == "SUPER_ADMIN" || actorRole == "ADMIN";
let query = req.query ?? {};
if (type(query) != "object") {
  return {deleted: false, statusCode: 400, reason: "Query must be a JSON object"};
}
if (!isPrivileged && !own_query_allowed(query, actor, actorEmail)) {
  return {deleted: false, authorized: false, statusCode: 403, reason: "Regular users must query their own username or email explicitly"};
}
let users = vdb.collection("auth_users");
let lookup = users.find(query, req.limit ?? 200);
let rows = lookup.data ?? [];
if (leng(rows) == 0) {
  return {deleted: false, notFound: true, statusCode: 404, reason: "No users matched the supplied query", query: query};
}
for (row : rows) {
  let targetRole = str((row ?? {}).role ?? "USER").upper();
  if (actorRole == "ADMIN" && targetRole == "SUPER_ADMIN") {
    return {deleted: false, authorized: false, statusCode: 403, reason: "ADMIN users cannot delete SUPER_ADMIN accounts"};
  }
}
let nowTs = datetime.now().isoformat();
let controls = vdb.collection("auth_session_controls");
let revokedUsers = [];
let revokeFailures = [];
for (row : rows) {
  let targetUsername = str((row ?? {}).username ?? "").trim();
  if (targetUsername == "") {
    continue;
  }
  let existing = controls.find({username: {$eq: targetUsername}}, 1);
  let controlRows = existing.data ?? [];
  let sessionVersion = 1;
  if (leng(controlRows) > 0) {
    let currentVersion = controlRows[0].sessionVersion ?? 1;
    if (currentVersion != "") {
      sessionVersion = currentVersion + 1;
    }
  }
  let revokePayload = {username: targetUsername, sessionVersion: sessionVersion, revokeAll: true, revokedAt: nowTs, excludeCurrentSession: false, excludedTokenHash: "", updatedAt: nowTs, updatedBy: actor, reason: "account_deleted"};
  let revokeSave = {};
  if (leng(controlRows) > 0) {
    revokeSave = controls.update({username: {$eq: targetUsername}}, revokePayload);
  } else {
    revokeSave = controls.insert(revokePayload);
  }
  if (revokeSave.ok == false) {
    revokeFailures.add({username: targetUsername, result: revokeSave});
  } else {
    revokedUsers.add({username: targetUsername, sessionVersion: sessionVersion});
  }
}
if (leng(revokeFailures) > 0) {
  return {deleted: false, statusCode: 500, reason: "Failed to revoke all user sessions before delete", revokeFailures: revokeFailures, revokedUsers: revokedUsers, query: query};
}
let deleteRes = users.delete(query);
if (!(deleteRes.ok ?? false)) {
  return {deleted: false, statusCode: 400, reason: deleteRes.error ?? "Delete failed", result: deleteRes};
}
let deletedUsers = [];
let ownOnly = true;
for (row : rows) {
  let username = str((row ?? {}).username ?? "").trim();
  if (username != "") {
    deletedUsers.add(username);
    if (username != actor) {
      ownOnly = false;
    }
  }
}
return {deleted: true, usernames: deletedUsers, count: leng(deletedUsers), ownDelete: ownOnly, sessionsRevoked: true, revokedUsers: revokedUsers, query: query, result: deleteRes};

ep_register_admin.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let authCtx = req.auth ?? {};
let actor = str(authCtx.username ?? authCtx.sub ?? "").trim();
let actorRole = str(authCtx.role ?? "").upper();
if (actorRole != "SUPER_ADMIN" && actorRole != "ADMIN") {
  return {created: false, authorized: false, statusCode: 403, reason: "Only SUPER_ADMIN or ADMIN can use register"};
}
let body = req.body ?? {};
let username = str(body.username ?? req.username ?? "").trim();
let email = str(body.email ?? req.email ?? "").trim();
let password = str(body.password ?? req.password ?? "").trim();
let profile = body.profile ?? {};
let requestedRole = str(body.role ?? req.role ?? "USER").upper();
if (requestedRole == "APP") {
  requestedRole = "APPLICATION";
}
if (username == "" || email == "" || password == "") {
  return {created: false, statusCode: 400, reason: "username, email and password are required"};
}
if (requestedRole == "SUPER_ADMIN") {
  return {created: false, authorized: false, statusCode: 403, reason: "register route cannot create SUPER_ADMIN users"};
}
if (actorRole == "ADMIN" && (requestedRole == "ADMIN" || requestedRole == "SUPER_ADMIN")) {
  return {created: false, authorized: false, statusCode: 403, reason: "ADMIN users can only create USER or APPLICATION accounts"};
}
let users = vdb.collection("auth_users");
let lookup = users.find({username: {$eq: username}}, 1);
let rows = lookup.data ?? [];
if (leng(rows) > 0) {
  return {created: false, statusCode: 409, reason: "User already exists", username: username};
}
let nowTs = datetime.now().isoformat();
let storedHash = crypto.sha256(password);
let defaultRbac = {scopes: ["USER"], abilities: ["auth.self.read", "auth.self.update"]};
let adminRbac = {scopes: ["ADMIN", "USER_MANAGE", "USER_READ", "USER_WRITE"], abilities: ["auth.manage", "auth.read", "auth.write"]};
let selectedRbac = requestedRole == "ADMIN" ? (body.rbac ?? req.rbac ?? adminRbac) : (body.rbac ?? req.rbac ?? defaultRbac);
let created = users.insert({username: username, email: email, passwordHash: storedHash, role: requestedRole, profile: profile, rbac: selectedRbac, createdAt: nowTs, updatedAt: nowTs, createdBy: actor});
return {created: created.ok ?? false, username: username, role: requestedRole, inserted: created.data ?? created, createdBy: actor, authModel: "AuthUser"};

ep_signout_all.versaScript:
json_xml import *;
vdb import *;
http import *;
email import *;
crypto import *;
jwt import *;
time import *;
datetime import *;

let req = params;
let authCtx = req.auth ?? {};
let username = str(authCtx.username ?? authCtx.sub ?? "").trim();
if (username == "") {
  return {ok: false, statusCode: 401, reason: "Missing authenticated user context"};
}
let body = req.body ?? {};
let excludeCurrent = body.exclude_current_session == true || body.excludeCurrentSession == true || req.exclude_current_session == true || req.excludeCurrentSession == true;
let nowTs = datetime.now().isoformat();
let controls = vdb.collection("auth_session_controls");
let currentToken = str(req.bearerToken ?? req.authToken ?? req.token ?? "").trim();
let tokenHash = currentToken != "" ? crypto.sha256(currentToken) : "";
if (excludeCurrent && tokenHash == "") {
  return {ok: false, statusCode: 400, reason: "Current bearer token is required when exclude_current_session=true"};
}
let existing = controls.find({username: {$eq: username}}, 1);
let rows = existing.data ?? [];
let nextSessionVersion = 1;
if (leng(rows) > 0) {
  let currentVersion = rows[0].sessionVersion ?? 1;
  if (currentVersion != "") {
    nextSessionVersion = currentVersion + 1;
  }
}
let payload = {username: username, sessionVersion: nextSessionVersion, revokeAll: true, revokedAt: nowTs, updatedAt: nowTs, updatedBy: username, reason: "signout_all", excludeCurrentSession: excludeCurrent, excludedTokenHash: excludeCurrent ? tokenHash : ""};
let saveRes = {};
if (leng(rows) > 0) {
  saveRes = controls.update({username: {$eq: username}}, payload);
} else {
  saveRes = controls.insert(payload);
}
return {ok: saveRes.ok ?? true, statusCode: saveRes.ok == false ? 500 : 200, username: username, revokedAllSessions: true, exclude_current_session: excludeCurrent, sessionVersion: nextSessionVersion, updated: saveRes};
